static void fft(std::vector<std::complex<double>>&a){const unsigned n=unsigned(a.size());for(unsigned i=1,j=0;i<n;++i){unsigned bit=n>>1;for(;j&bit;bit>>=1)j^=bit;j^=bit;if(i<j)std::swap(a[i],a[j]);}for(unsigned len=2;len<=n;len*=2){std::complex<double>wlen=std::polar(1.,-2*pi/len);for(unsigned i=0;i<n;i+=len){std::complex<double>w=1;for(unsigned j=0;j<len/2;++j){auto u=a[i+j],v=a[i+j+len/2]*w;a[i+j]=u+v;a[i+j+len/2]=u-v;w*=wlen;}}}}
